mapper.select:
SELECT stock_id, trade_date, close_price, volume FROM ( SELECT stock_id, trade_date, close_price, volume, ROW_NUMBER() OVER (PARTITION BY stock_id ORDER BY trade_date DESC) AS rn FROM stock_daily_price WHERE stock_id IN
#{id}
) ranked WHERE rn <= 2 ORDER BY stock_id, trade_date DESC

SELECT MIN(trade_date) AS first_trade_date, COUNT(*) AS trading_day_count
FROM stock_daily_price
WHERE stock_id = #{stockId}

SELECT trade_date FROM stock_daily_price
WHERE stock_id = #{stockId} AND trade_date < #{beforeDate}
ORDER BY trade_date DESC
LIMIT #{limit}

SELECT MAX(high_price) AS high_price, MIN(low_price) AS low_price
FROM (
    SELECT high_price, low_price FROM stock_daily_price
    WHERE stock_id = #{stockId} AND trade_date <= #{tradeDate}
    ORDER BY trade_date DESC
    LIMIT #{days}
) recent
